      name="q"
      class="topbar__input"
      aria-label="Search heroes and missions"
      placeholder="Search heroes, missions"
    />
    <button hlmBtn type="submit" variant="ghost" size="icon" aria-label="Search">
      <ng-icon hlmIcon name="lucideSearch" />
