  Injured: 'warning',
  MIA: 'destructive',
};

// "Dr. Ion" -> "DI", "The Tinkerer" -> "TT".
export function initialsOf(name: string): string {
  return name
    .replace(/[^\p{L}\s]/gu, '')
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((word) => word.charAt(0).toUpperCase())
    .join('');
}

