    this.threatService
      .threats()
      .map((threat) => ({
        threat,
        tier: clearanceLabel(threat.tier),
        live: this.missionService
          .missions()
          .filter((mission) => mission.threatId === threat.id && mission.status === 'Live').length,
        statusBadge: THREAT_BADGE[threat.status],
      }))
      .sort((a, b) => b.threat.tier - a.threat.tier),
  );
}

